import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { courseAPI } from '../api/api';

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => { fetchCourses(); }, []);

  const fetchCourses = async () => {
    setLoading(true);
    try {
      const res = await courseAPI.getAll();
      setCourses(res.data);
    } catch { } finally { setLoading(false); }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!search.trim()) return fetchCourses();
    const res = await courseAPI.search(search);
    setCourses(res.data);
  };

  const COLORS = ['#e94560','#16c79a','#f5a623','#a29bfe','#74b9ff','#fd79a8'];

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <h2 style={styles.heading}>Explore Courses</h2>
        <form onSubmit={handleSearch} style={styles.searchRow}>
          <input style={styles.searchInput} placeholder="Search courses..."
            value={search} onChange={e => setSearch(e.target.value)} />
          <button style={styles.searchBtn} type="submit">🔍 Search</button>
        </form>
      </div>

      {loading ? (
        <div style={styles.loading}>Loading courses...</div>
      ) : courses.length === 0 ? (
        <div style={styles.empty}>No courses found.</div>
      ) : (
        <div style={styles.grid}>
          {courses.map((c, i) => (
            <div key={c.id} style={styles.card}>
              <div style={{ ...styles.thumb, background: COLORS[i % COLORS.length] }}>
                {c.thumbnailUrl
                  ? <img src={c.thumbnailUrl} alt={c.title} style={{ width:'100%', height:'100%', objectFit:'cover' }} />
                  : <span style={styles.thumbIcon}>📚</span>}
              </div>
              <div style={styles.cardBody}>
                <div style={styles.category}>{c.category || 'General'}</div>
                <div style={styles.courseTitle}>{c.title}</div>
                <div style={styles.desc}>{c.description?.slice(0, 80)}...</div>
                <div style={styles.meta}>
                  <span>👨‍🏫 {c.instructorName}</span>
                  <span>👥 {c.enrollmentCount} students</span>
                </div>
                {c.durationMinutes && <div style={styles.duration}>⏱ {c.durationMinutes} min</div>}
                <Link to={`/courses/${c.id}`} style={styles.viewBtn}>View Course</Link>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const styles = {
  page: { maxWidth:1100, margin:'0 auto', padding:'32px 24px' },
  header: { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:28, flexWrap:'wrap', gap:16 },
  heading: { color:'#1a1a2e', fontSize:26, margin:0 },
  searchRow: { display:'flex', gap:8 },
  searchInput: { padding:'10px 14px', borderRadius:8, border:'1px solid #ddd', fontSize:14, width:240 },
  searchBtn: { padding:'10px 16px', background:'#e94560', color:'#fff', border:'none', borderRadius:8, cursor:'pointer' },
  loading: { textAlign:'center', padding:60, color:'#888' },
  empty: { textAlign:'center', padding:60, color:'#aaa' },
  grid: { display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(280px,1fr))', gap:20 },
  card: { background:'#fff', borderRadius:14, overflow:'hidden', boxShadow:'0 2px 16px rgba(0,0,0,0.08)', transition:'transform 0.2s' },
  thumb: { height:140, display:'flex', alignItems:'center', justifyContent:'center' },
  thumbIcon: { fontSize:48 },
  cardBody: { padding:18 },
  category: { fontSize:11, color:'#e94560', fontWeight:600, textTransform:'uppercase', letterSpacing:1, marginBottom:6 },
  courseTitle: { fontWeight:700, color:'#1a1a2e', fontSize:15, marginBottom:6 },
  desc: { color:'#777', fontSize:13, marginBottom:12, lineHeight:1.5 },
  meta: { display:'flex', gap:16, color:'#999', fontSize:12, marginBottom:8 },
  duration: { color:'#aaa', fontSize:12, marginBottom:12 },
  viewBtn: { display:'block', textAlign:'center', padding:'9px 0', background:'#1a1a2e', color:'#fff', borderRadius:8, textDecoration:'none', fontSize:13, fontWeight:600 },
};
